--
-- Name: review_claim(uuid, boolean, numeric, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.review_claim(_id uuid, _approve boolean, _amount numeric, _note text) RETURNS public.claims
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  rec public.claims;
BEGIN
  IF NOT public.has_role(auth.uid(), 'super_admin') THEN
    RAISE EXCEPTION 'Only admin can review claims';
  END IF;

  SELECT * INTO rec FROM public.claims WHERE id = _id FOR UPDATE;
  IF rec IS NULL THEN RAISE EXCEPTION 'Claim not found'; END IF;
  IF rec.status <> 'pending' THEN RAISE EXCEPTION 'Claim already reviewed'; END IF;

  UPDATE public.claims
     SET status = CASE WHEN _approve THEN 'approved' ELSE 'rejected' END,
         approved_amount = CASE WHEN _approve THEN COALESCE(_amount, rec.claim_amount) ELSE 0 END,
         review_note = NULLIF(btrim(coalesce(_note, '')), ''),
         reviewed_by = auth.uid(),
         reviewed_at = now()
   WHERE id = _id
   RETURNING * INTO rec;

  RETURN rec;
END;
$$;


ALTER FUNCTION public.review_claim(_id uuid, _approve boolean, _amount numeric, _note text) OWNER TO postgres;

