    reference text,
    notes text,
    status text DEFAULT 'pending'::text NOT NULL,
    created_by uuid DEFAULT auth.uid() NOT NULL,
    created_role text DEFAULT 'distributor'::text NOT NULL,
    approved_by uuid,
    approval_note text,
    approved_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT csa_payments_amount_check CHECK ((amount > (0)::numeric)),
    CONSTRAINT csa_payments_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text])))
);


ALTER TABLE public.csa_payments OWNER TO postgres;

--
-- Name: review_csa_payment(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.review_csa_payment(_id uuid, _approve boolean, _note text DEFAULT ''::text) RETURNS public.csa_payments
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _row public.csa_payments;
BEGIN
  IF NOT (public.has_role(auth.uid(), 'csa') OR public.has_role(auth.uid(), 'super_admin')) THEN
    RAISE EXCEPTION 'Only CSA or admin can review payments';
  END IF;

  SELECT * INTO _row FROM public.csa_payments WHERE id = _id FOR UPDATE;
  IF _row.id IS NULL THEN RAISE EXCEPTION 'Payment not found'; END IF;
  IF _row.status <> 'pending' THEN RAISE EXCEPTION 'Payment already reviewed'; END IF;

  IF _approve THEN
    UPDATE public.distributors
    SET outstanding = GREATEST(outstanding - _row.amount, 0)
    WHERE id = _row.distributor_id;
  END IF;

  UPDATE public.csa_payments
  SET status = CASE WHEN _approve THEN 'approved' ELSE 'rejected' END,
      approved_by = auth.uid(),
      approval_note = NULLIF(_note, ''),
      approved_at = now()
  WHERE id = _id
  RETURNING * INTO _row;

  RETURN _row;
END; $$;


ALTER FUNCTION public.review_csa_payment(_id uuid, _approve boolean, _note text) OWNER TO postgres;

